val crowdEffectsOn = menuSoundServices?.settings?.soundEffects ?: false
LaunchedEffect(crowdWanted, crowdEffectsOn) {
    val sound = menuSoundServices?.sound ?: return@LaunchedEffect
    if (!crowdWanted) {
